SELECT public.assert_rls(NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename IN ('diagrams','diagram_collaborators','shared_diagrams') AND policyname IN ('owner_all','collaborator_read','adder_all','self_read','creator_all','read_active')), 'remove every legacy permissive policy on diagram tables');
SELECT public.assert_rls(pg_get_function_result('public.add_diagram_collaborator(uuid,text,text)'::regprocedure) = 'json', 'preserve deployed collaborator mutation return type');
SELECT public.assert_rls(pg_get_function_result('public.get_diagram_collaborators(uuid)'::regprocedure) = 'TABLE(diagram_id uuid, user_id uuid, role text, added_by uuid, created_at timestamp with time zone, email text)', 'preserve deployed collaborator listing UUID return columns');
SELECT public.assert_rls(NOT has_function_privilege('anon', 'public.add_diagram_collaborator(uuid,text,text)', 'EXECUTE'), 'anonymous cannot invoke collaborator mutation');
SELECT public.assert_rls(NOT has_function_privilege('anon', 'public.get_diagram_collaborators(uuid)', 'EXECUTE'), 'anonymous cannot invoke collaborator email listing');
SELECT public.assert_rls(NOT has_function_privilege('anon', 'public.remove_diagram_collaborator(uuid,uuid)', 'EXECUTE'), 'anonymous cannot invoke collaborator revocation');
SELECT public.assert_rls(NOT EXISTS (SELECT 1 FROM unnest(ARRAY['anon','authenticated']) r WHERE has_function_privilege(r, 'public.prevent_diagram_user_id_change()', 'EXECUTE')), 'client roles cannot invoke trigger function directly');
SELECT public.assert_rls(NOT EXISTS (SELECT 1 FROM unnest(ARRAY['anon','authenticated']) r CROSS JOIN unnest(ARRAY['diagrams','shared_diagrams','diagram_collaborators']) t WHERE has_table_privilege(r, 'public.' || t, 'TRUNCATE')), 'client roles cannot truncate tables outside RLS');
SET ROLE anon;
SELECT public.assert_rls((SELECT count(*) = 1 FROM public.get_shared_diagram_by_token('fixture-active')), 'active token opens one diagram');
SELECT public.assert_rls((SELECT count(*) = 0 FROM public.get_shared_diagram_by_token('fixture-expired')), 'expired token denied');
SELECT public.assert_rls((SELECT count(*) = 0 FROM public.get_shared_diagram_by_token('fixture-inactive')), 'inactive token denied');
SELECT public.assert_rls((SELECT count(*) = 0 FROM public.get_shared_diagram_by_token('unknown')), 'unknown token denied');
SELECT public.assert_rls((SELECT count(*) = 0 FROM public.get_shared_diagram_by_token(NULL)), 'null token denied');
SELECT public.assert_rls((SELECT count(*) = 0 FROM public.get_shared_diagram_by_token('')), 'empty token denied');
SELECT public.assert_rls((SELECT count(*) = 0 FROM public.get_shared_diagram_by_token(repeat('x', 16385))), 'oversized unknown token cannot expose content');
DO $$ BEGIN
  BEGIN PERFORM * FROM public.shared_diagrams; RAISE EXCEPTION 'Anonymous share enumeration was allowed'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
END $$;
RESET ROLE;
SET ROLE authenticated;
SELECT set_config('request.jwt.claim.sub', '', false);
SELECT public.assert_rls(NOT (public.add_diagram_collaborator('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa', 'viewer@example.invalid', 'editor')->>'success')::boolean, 'mutation rejects missing identity');
SELECT public.assert_rls((SELECT count(*) = 0 FROM public.get_diagram_collaborators('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa')), 'missing identity cannot list collaborator emails');
SELECT set_config('request.jwt.claim.sub', '22222222-2222-4222-8222-222222222222', false);
SELECT public.assert_rls((SELECT count(*) = 0 FROM public.diagrams WHERE id = 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'), 'outsider cannot read diagram');
SELECT public.assert_rls(NOT (public.add_diagram_collaborator('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa', 'viewer@example.invalid', 'editor')->>'success')::boolean, 'outsider cannot invite');
DO $$ BEGIN
  BEGIN INSERT INTO public.diagram_collaborators VALUES('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','22222222-2222-4222-8222-222222222222','owner','22222222-2222-4222-8222-222222222222', now()); RAISE EXCEPTION 'Self-granted ownership was allowed'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
  BEGIN UPDATE public.diagrams SET user_id='11111111-1111-4111-8111-111111111111' WHERE id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'; RAISE EXCEPTION 'Ownership reassignment was allowed'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
END $$;
SELECT set_config('request.jwt.claim.sub', '11111111-1111-4111-8111-111111111111', false);
SELECT public.assert_rls((public.add_diagram_collaborator('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa', 'viewer@example.invalid', 'viewer')->>'success')::boolean, 'owner can invite viewer');
SELECT public.assert_rls(NOT (public.add_diagram_collaborator('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa', 'viewer@example.invalid', 'owner')->>'success')::boolean, 'RPC rejects elevated owner role');
SELECT public.assert_rls(NOT (public.add_diagram_collaborator('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa', 'viewer@example.invalid', NULL)->>'success')::boolean, 'RPC rejects null role without a constraint exception');
SELECT public.assert_rls(NOT (public.add_diagram_collaborator('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa', 'viewer@example.invalid', '')->>'success')::boolean, 'RPC rejects empty role');
SELECT public.assert_rls(NOT (public.add_diagram_collaborator('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa', 'viewer@example.invalid', '   ')->>'success')::boolean, 'RPC rejects whitespace role');
SELECT public.assert_rls(NOT (public.add_diagram_collaborator('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa', 'viewer@example.invalid', 'admin')->>'success')::boolean, 'RPC rejects unknown privileged role');
SELECT set_config('request.jwt.claim.sub', '33333333-3333-4333-8333-333333333333', false);
SELECT public.assert_rls((SELECT count(*) = 1 FROM public.diagrams WHERE id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'), 'viewer can read diagram');
WITH changed AS (UPDATE public.diagrams SET title='viewer change' WHERE id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa' RETURNING id) SELECT public.assert_rls(count(*)=0, 'viewer cannot edit') FROM changed;
SELECT public.assert_rls(NOT (public.add_diagram_collaborator('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa', 'outsider@example.invalid', 'editor')->>'success')::boolean, 'viewer cannot manage collaborators');
SELECT set_config('request.jwt.claim.sub', '11111111-1111-4111-8111-111111111111', false);
SELECT public.assert_rls((public.add_diagram_collaborator('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa', 'viewer@example.invalid', 'editor')->>'success')::boolean, 'owner can upgrade to editor');
SELECT set_config('request.jwt.claim.sub', '33333333-3333-4333-8333-333333333333', false);
WITH changed AS (UPDATE public.diagrams SET title='editor change' WHERE id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa' RETURNING id) SELECT public.assert_rls(count(*)=1, 'editor can edit') FROM changed;
SELECT set_config('request.jwt.claim.sub', '11111111-1111-4111-8111-111111111111', false);
SELECT public.assert_rls((public.remove_diagram_collaborator('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa', '33333333-3333-4333-8333-333333333333')->>'success')::boolean, 'owner can revoke collaborator');
SELECT set_config('request.jwt.claim.sub', '33333333-3333-4333-8333-333333333333', false);
SELECT public.assert_rls((SELECT count(*) = 0 FROM public.diagrams WHERE id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'), 'revocation removes read access');
RESET ROLE;
-- Legacy owner rows must survive authorized management of viewer/editor rows.
INSERT INTO public.diagram_collaborators VALUES ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa', '22222222-2222-4222-8222-222222222222', 'owner', '11111111-1111-4111-8111-111111111111', now());
SET ROLE authenticated;
SELECT set_config('request.jwt.claim.sub', '11111111-1111-4111-8111-111111111111', false);
SELECT public.assert_rls(NOT (public.add_diagram_collaborator('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa', 'outsider@example.invalid', 'viewer')->>'success')::boolean, 'owner collaborator cannot be downgraded');
SELECT public.assert_rls(NOT (public.remove_diagram_collaborator('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa', '22222222-2222-4222-8222-222222222222')->>'success')::boolean, 'owner collaborator cannot be removed');
RESET ROLE;
